#include <iostream>
#include <string>
#include <vector>

// Base class Object
class Object {
public:
    virtual ~Object() {}
};

// Component class Motor
class Motor {
    int horsepower;
public:
    Motor(int hp) : horsepower(hp) {}
    void run() const { std::cout << "Motor running at " << horsepower << " HP.\n"; }
};

// Vehicle base class inheriting from Object
class Vehicle : public Object {
protected:
    std::string brand;
    int year;
    Motor motor;
public:
    Vehicle(std::string b, int y, int hp) : brand(b), year(y), motor(hp) {}
    virtual void display() = 0; // Polymorphism
    virtual ~Vehicle() {}
};

// Car class
