    double length;
public:
    Boat(std::string b, int y, int hp, double l) : Vehicle(b, y, hp), length(l) {}
    void display() override { std::cout << "Boat: " << brand << " (" << year << "), Length: " << length << "ft\n"; }
};

// Airplane class
