class Car : public Vehicle {
private:
    int doors;
public:
    Car(std::string b, int y, int hp, int d) : Vehicle(b, y, hp), doors(d) {}
    ~Car() override { std::cout << "Car destroyed\n"; }
    void setDoors(int d) { doors = d; }
    int getDoors() const { return doors; }
    void display() override { std::cout << "Car: " << brand << " (" << year << "), Doors: " << doors << "\n"; }
};

/**
 * Boat subclass inheriting from Vehicle.
 */
class Boat : public Vehicle {
private:
    double length;
public:
    Boat(std::string b, int y, int hp, double l) : Vehicle(b, y, hp), length(l) {}
    ~Boat() override { std::cout << "Boat destroyed\n"; }
    void setLength(double l) { length = l; }
    double getLength() const { return length; }
    void display() override { std::cout << "Boat: " << brand << " (" << year << "), Length: " << length << "ft\n"; }
};

/**
 * Airplane subclass inheriting from Vehicle.
 */
class Airplane : public Vehicle {
private:
    int altitude;
public:
    Airplane(std::string b, int y, int hp, int a) : Vehicle(b, y, hp), altitude(a) {}
    ~Airplane() override { std::cout << "Airplane destroyed\n"; }
    void setAltitude(int a) { altitude = a; }
    int getAltitude() const { return altitude; }
    void display() override { std::cout << "Airplane: " << brand << " (" << year << "), Max Alt: " << altitude << "ft\n"; }
};

int main() {
    // Demonstration of polymorphism using a vector of Vehicle pointers.
    std::vector<Vehicle*> fleet;
    fleet.push_back(new Car("Toyota", 2020, 150, 4));
    fleet.push_back(new Boat("Yamaha", 2018, 200, 25.5));
    fleet.push_back(new Airplane("Boeing", 2022, 5000, 35000));

    for (Vehicle* v : fleet) {
        v->display();
    }

    // Cleaning up allocated memory.
    for (Vehicle* v : fleet) {
        delete v;
    }
    return 0;
}
```

P.P.S This C++ program provides a robust implementation of object-oriented design, featuring a multi-level inheritance structure, component composition, and proper memory management through virtual destructors.

